7	///
8	/// A section is a root key of the rendered TOON document: a list or text section under its `name`, a KV section as its
9	/// item keys. Root keys must be unique, so two sections cannot share a name, and no name or KV key may be one of the
10	/// keys michi writes itself (`budget`, `sections`, `provenance`, `truncated`, `totalCount`, `help`, `recovery`). A
11	/// response that breaks this renders the `toon_validation_failed` error naming the key, never invalid TOON.
12	///
13	/// # Stability
14	///
15	/// The multi-section envelope (this type, [`crate::BudgetSummary`], [`crate::ProvenanceBlock`]) is unstable. It
16	/// shipped ahead of a second independent consumer (ADR 10), so its shape may change before 1.0, and 1.0 promises only
17	/// what consumers have used by then.
18	#[derive(Debug, Clone)]
19	#[non_exhaustive]
20	pub struct Section {
21	    /// The section's type name: the identifier at the head of its TOON line, and the key of a text body. A KV body
22	    /// prints no heading, so there the name only labels it for the caller (and for `sections` in JSON).
23	    pub name: String,
24	    /// The section's contents.
25	    pub body: SectionBody,
26	    /// How many items this section carries, as set by the constructor. Rendering never trusts this field for `Toon`
27	    /// and `Kv` bodies: it counts `rows` / `items` itself (see [`Section::count`]). `Text` bodies keep the declared
28	    /// value, since michi cannot count items in prose.
29	    pub returned_count: usize,
30	    /// How many existed before truncation. `Some(n)` with `n > returned_count` renders `totalCount: n`.
31	    pub total_count: Option<usize>,
32	    /// Whether producing this section dropped anything. Carried for the caller; it does not change the text render.
33	    pub truncated: bool,
34	}
35	
36	/// What a [`Section`] holds.
37	#[derive(Debug, Clone)]
38	#[non_exhaustive]
39	pub enum SectionBody {
40	    /// A uniform list, rendered as a TOON list with the response's per-cell truncation applied.
41	    Toon {
42	        /// Ordered, distinct field names.
43	        fields: Vec<String>,
44	        /// Rows, parallel to `fields`.
45	        rows: Vec<Vec<Value>>,
46	    },
47	    /// A single receipt or a small set of labelled scalars.
48	    Kv(Vec<KvItem>),
49	    /// One string value, rendered as `name: <value>` and escaped like any other TOON string (quoted when it has a
50	    /// newline, a colon, or looks like a number). Prose cannot start a line of its own, so it cannot forge a `help[]`
51	    /// line. It is not a way to insert a fragment of TOON.
52	    Text(String),
53	}
54	
55	impl Section {
56	    /// A TOON list section. `returned_count` is `rows.len()`.
57	    #[must_use]
58	    pub fn toon(name: impl Into<String>, fields: Vec<String>, rows: Vec<Vec<Value>>) -> Self {
59	        Self::with(name, rows.len(), SectionBody::Toon { fields, rows })
60	    }
61	
62	    /// A key-value section. `returned_count` is `items.len()`.
63	    #[must_use]
64	    pub fn kv(name: impl Into<String>, items: Vec<KvItem>) -> Self {
65	        Self::with(name, items.len(), SectionBody::Kv(items))
66	    }
67	
