69	    /// non-empty text and 0 for empty; set it with [`returned_count`](Self::returned_count). A `totalCount` renders
70	    /// as for the other bodies, when [`total_count`](Self::total_count) exceeds that count.
71	    #[must_use]
72	    pub fn text(name: impl Into<String>, body: impl Into<String>) -> Self {
73	        let body = body.into();
74	        Self::with(name, usize::from(!body.is_empty()), SectionBody::Text(body))
75	    }
76	
77	    fn with(name: impl Into<String>, returned_count: usize, body: SectionBody) -> Self {
78	        Self { name: name.into(), body, returned_count, total_count: None, truncated: false }
79	    }
80	
81	    /// Record the pre-truncation count. `Some(n)` with `n` greater than the returned count renders `totalCount: n`.
82	    #[must_use]
83	    pub fn total_count(mut self, total: Option<usize>) -> Self {
84	        self.total_count = total;
85	        self
86	    }
87	
88	    /// Record whether producing this section dropped anything.
89	    #[must_use]
90	    pub fn truncated(mut self, truncated: bool) -> Self {
91	        self.truncated = truncated;
92	        self
93	    }
94	
95	    /// Declare how many items a `Text` body carries. Ignored for `Toon` and `Kv` bodies, whose count is derived.
96	    #[must_use]
97	    pub fn returned_count(mut self, n: usize) -> Self {
98	        if matches!(self.body, SectionBody::Text(_)) {
99	            self.returned_count = n;
100	        }
101	        self
102	    }
103	
104	    /// The count rendering uses: `rows.len()` or `items.len()` for `Toon` and `Kv` bodies, the declared
105	    /// `returned_count` for `Text`. A hand-edited `returned_count` field cannot disagree with the body.
106	    #[must_use]
107	    pub fn count(&self) -> usize {
108	        match &self.body {
109	            SectionBody::Toon { rows, .. } => rows.len(),
110	            SectionBody::Kv(items) => items.len(),
111	            SectionBody::Text(_) => self.returned_count,
112	        }
113	    }
114	
115	    /// The `totalCount` to render: `total_count` only when it exceeds [`count`](Self::count).
116	    pub(crate) fn shown_total(&self) -> Option<usize> {
117	        self.total_count.filter(|n| *n > self.count())
118	    }
119	}
