1	use crate::budget::BudgetSummary;
2	use crate::hints::Hint;
3	use crate::kv::KvItem;
4	use crate::provenance::ProvenanceBlock;
5	use crate::recovery::RecoveryHint;
6	use crate::section::{Section, SectionBody};
7	use crate::toon::Value;
8	
9	/// The serialisation format for `AgentResponse::render`.
10	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
11	#[non_exhaustive]
12	pub enum OutputFormat {
13	    /// Plain-text TOON / kv format. Default.
14	    #[default]
15	    Text,
16	    /// Compact JSON object.
17	    Json,
18	}
19	
20	/// Default per-cell truncation limit used by [`AgentResponse::new`].
21	pub const DEFAULT_TRUNCATE_CELLS: usize = 200;
22	
23	/// Builder for an agent-facing response: an ordered list of [`Section`]s, an optional budget report and provenance
24	/// block, hints and recovery hints.
25	#[derive(Debug, Clone)]
26	#[non_exhaustive]
27	pub struct AgentResponse {
28	    /// The type name given to [`new`](Self::new): it names the sections that [`items`](Self::items) and
29	    /// [`kv_items`](Self::kv_items) append, and the empty list an untouched response renders.
30	    name: String,
31	    /// Per-cell cap for every `Toon` section, set with [`truncate_cells_at`](Self::truncate_cells_at).
32	    max_cell_len: usize,
33	    /// The caller's instruction for getting a cut cell in full, set with [`truncation_hint`](Self::truncation_hint).
34	    truncation_hint: Option<String>,
35	    /// Every block, in call order. The one place a response keeps its body.
36	    sections: Vec<Section>,
37	    /// Response-level budget report, set with `budget()`.
38	    budget: Option<BudgetSummary>,
39	    /// Response-level provenance block, set with `provenance()`.
40	    provenance: Option<ProvenanceBlock>,
41	    hints: Vec<Hint>,
42	    recovery: Vec<RecoveryHint>,
43	    is_error: bool,
44	    human_content: Option<String>,
45	}
46	
47	impl AgentResponse {
48	    /// Create a new, empty response for the given type name. The name labels the sections that
49	    /// [`items`](Self::items) and [`kv_items`](Self::kv_items) add. A response that never gets a section, budget or
50	    /// provenance renders `name: []`, the definitive empty list.
51	    pub fn new(type_name: impl Into<String>) -> Self {
52	        Self {
53	            name: type_name.into(),
54	            max_cell_len: DEFAULT_TRUNCATE_CELLS,
55	            truncation_hint: None,
56	            sections: Vec::new(),
57	            budget: None,
58	            provenance: None,
59	            hints: Vec::new(),
60	            recovery: Vec::new(),
61	            is_error: false,
62	            human_content: None,
63	        }
64	    }
65	
66	    /// Append a TOON list section named for the response's type: shorthand for
67	    /// `section(Section::toon(name, fields, rows))`. Every call adds a section, rendered in call order.
68	    ///
69	    /// Sections are root keys, and this shorthand gives each the same name, so for one list per response only: a
70	    /// second `items()` call repeats the key `name`, and the response renders the `toon_validation_failed` error
71	    /// naming it (and `is_error()` is true) instead of invalid TOON. Mixing with [`kv_items`](Self::kv_items) works
72	    /// while no KV key equals the type name. For several lists, give each its own name with
73	    /// `.section(Section::toon(distinct_name, ..))`. To report a total, build the section yourself and set
74	    /// [`Section::total_count`].
75	    #[must_use]
76	    pub fn items(self, rows: Vec<Vec<Value>>, fields: &[&str]) -> Self {
77	        let name = self.name.clone();
78	        self.section(Section::toon(name, fields.iter().map(|s| (*s).to_string()).collect(), rows))
79	    }
80	
81	    /// Append a section for a cut list, in one call: `section` gets `totalCount` (`outcome.total_before`) and its
82	    /// `truncated` flag from `outcome`, and, only when something was cut, [`TruncationOutcome::hint`](crate::truncation::TruncationOutcome::hint) is appended to
83	    /// the hints. The count and the `help[]` line therefore always describe the same cut.
84	    ///
85	    /// The response holds TOON [`Value`] rows, not the caller's `T`, so build `section` from `outcome.kept`
86	    /// (converted to rows). `totalCount` renders only when `total_before` exceeds the section's rows.
87	    ///
88	    /// ```
89	    /// use michi_core::toon::Value;
90	    /// use michi_core::{truncate_by_count, AgentResponse, OutputFormat, Section};
91	    ///
92	    /// let outcome = truncate_by_count(vec![1, 2, 3, 4], 2);
93	    /// let rows = outcome.kept.iter().map(|n| vec![Value::Int(*n)]).collect();
94	    /// let r = AgentResponse::new("issues").truncated_section(
95	    ///     Section::toon("issues", vec!["n".into()], rows),
96	    ///     &outcome,
97	    ///     "pass --limit 4",
98	    /// );
99	    /// assert_eq!(
100	    ///     r.render(OutputFormat::Text),
101	    ///     "issues[2]{n}:\n  1\n  2\ntotalCount: 4\nhelp[1]: showing 2 of 4; pass --limit 4"
102	    /// );
103	    /// ```
104	    #[must_use]
105	    pub fn truncated_section<T>(
106	        mut self,
107	        section: Section,
108	        outcome: &crate::truncation::TruncationOutcome<T>,
109	        guidance: impl Into<String>,
110	    ) -> Self {
111	        if let Some(hint) = outcome.hint(guidance) {
112	            self.hints.push(hint);
113	        }
114	        self.section(section.total_count(Some(outcome.total_before)).truncated(outcome.truncated()))
115	    }
116	
117	    /// Append a KV section named for the response's type: shorthand for `section(Section::kv(name, items))`. The name
118	    /// is not printed for a KV body. Every call adds a section, but the item keys are root keys: two calls sharing a
119	    /// key render the `toon_validation_failed` error naming it. See [`items`](Self::items); for several KV sections
120	    /// use `.section(Section::kv(name, ..))` and keep the keys distinct.
121	    #[must_use]
122	    pub fn kv_items(self, items: Vec<KvItem>) -> Self {
123	        let name = self.name.clone();
124	        self.section(Section::kv(name, items))
125	    }
126	
127	    /// Append a section. Sections render in call order, the one place a response keeps its body: the caller owns
128	    /// ordering.
129	    ///
130	    /// The response's cell cap ([`truncate_cells_at`](Self::truncate_cells_at)) and truncation hint apply to every
131	    /// `Toon` body. A section's `totalCount` comes from [`Section::total_count`]. Each section is a root key of the
132	    /// document, so names must be distinct (see [`Section`]).
133	    #[must_use]
134	    pub fn section(mut self, section: Section) -> Self {
135	        self.sections.push(section);
136	        self
137	    }
138	
139	    /// Attach the response-level budget report; one per response, a second call replaces the first. It renders as a
140	    /// `budget:` block after the last section (see [`BudgetSummary`] for what it carries), and the per-section
141	    /// roll-up appears only when the response has two or more sections. michi renders the report; it never computes
142	    /// it.
143	    ///
144	    /// A response with a budget or provenance but no section has no body of its own: the empty `type: []` line that
145	    /// an untouched response renders is left out.
146	    #[must_use]
147	    pub fn budget(mut self, budget: BudgetSummary) -> Self {
148	        self.budget = Some(budget);
149	        self
150	    }
151	
152	    /// Attach the response-level provenance block; one per response, a second call replaces the first. It renders as
153	    /// a `provenance:` block after `budget:` (see [`ProvenanceBlock`]).
154	    #[must_use]
155	    pub fn provenance(mut self, provenance: ProvenanceBlock) -> Self {
156	        self.provenance = Some(provenance);
157	        self
158	    }
159	
160	    /// Append a contextual hint.
161	    #[must_use]
162	    pub fn hint(mut self, hint: impl Into<String>) -> Self {
163	        self.hints.push(Hint::new(hint));
164	        self
165	    }
166	
167	    /// Replace all contextual hints.
168	    #[must_use]
169	    pub fn hints(mut self, hints: Vec<Hint>) -> Self {
170	        self.hints = hints;
171	        self
172	    }
173	
174	    /// Append a recovery hint.
175	    #[must_use]
176	    pub fn recovery_hint(mut self, r: RecoveryHint) -> Self {
177	        self.recovery.push(r);
178	        self
179	    }
180	
181	    /// Set the max string cell length, in chars, before truncation on the TOON path. Default:
182	    /// [`DEFAULT_TRUNCATE_CELLS`].
183	    ///
184	    /// The limit counts characters before TOON escaping and quoting, so a cell that needs quotes or escapes is
185	    /// written longer than `limit` (see [`crate::toon::ToonOptions::max_cell_len`]). The KV path is never truncated.
186	    ///
187	    /// The cap shapes the text render only. The JSON `sections` (and so `structuredContent`) carry every cell in full:
188	    /// they are the canonical data, and the text is the token-saving view of it.
189	    #[must_use]
190	    pub fn truncate_cells_at(mut self, limit: usize) -> Self {
191	        self.max_cell_len = limit;
192	        self
193	    }
194	
195	    /// Set the caller's instruction for getting a cut TOON cell in full. When a cell was cut, michi adds one line to
196	    /// `help[]` (after your own hints) that names the `truncated` block and this instruction (see
197	    /// [`crate::toon::ToonOptions::truncation_hint`]). Unset by default: michi never invents a parameter the tool
198	    /// may not have, and the `truncated` block still reports each cut. Pass tool-author text, never data.
199	    #[must_use]
200	    pub fn truncation_hint(mut self, hint: impl Into<String>) -> Self {
201	        self.truncation_hint = Some(hint.into());
202	        self
203	    }
204	
205	    /// Mark this response as an error state.
206	    #[must_use]
207	    pub fn as_error(mut self) -> Self {
208	        self.is_error = true;
209	        self
210	    }
211	
212	    /// Attach a human-facing companion block (`audience: user`).
213	    #[must_use]
214	    pub fn human_content(mut self, text: impl Into<String>) -> Self {
215	        self.human_content = Some(text.into());
216	        self
217	    }
218	
219	    /// The caller's hints, then michi's own truncation line when there is one: a single `help` block.
220	    fn hints_with<'a>(&'a self, extra: &[Hint]) -> std::borrow::Cow<'a, [Hint]> {
221	        if extra.is_empty() {
222	            std::borrow::Cow::Borrowed(&self.hints)
223	        } else {
224	            let mut all = Vec::with_capacity(self.hints.len() + extra.len());
225	            all.extend(self.hints.iter().cloned());
226	            all.extend(extra.iter().cloned());
227	            std::borrow::Cow::Owned(all)
228	        }
229	    }
230	
231	    /// The options a `Toon` section renders by: the response's cell cap and truncation hint, the section's own
232	    /// `totalCount` rule. Copies the rows: `ToonOptions` owns them.
233	    fn section_options(
234	        &self,
235	        name: &str,
236	        fields: &[String],
237	        rows: &[Vec<Value>],
238	        shown_total: Option<usize>,
239	    ) -> crate::toon::ToonOptions {
240	        let mut opts = crate::toon::ToonOptions::new(name, fields.to_vec(), rows.to_vec());
241	        opts.total_count = shown_total;
242	        opts.max_cell_len = self.max_cell_len;
243	        opts.truncation_hint.clone_from(&self.truncation_hint);
244	        opts
245	    }
246	
247	    /// The blocks to render: the sections, or, for a response with nothing at all, the one empty list that names
248	    /// its type. A budget or provenance block stands alone, with no empty list before it.
249	    fn blocks(&self) -> std::borrow::Cow<'_, [Section]> {
250	        if self.sections.is_empty() && self.budget.is_none() && self.provenance.is_none() {
251	            std::borrow::Cow::Owned(vec![Section::toon(self.name.as_str(), Vec::new(), Vec::new())])
252	        } else {
253	            std::borrow::Cow::Borrowed(&self.sections)
254	        }
255	    }
256	
257	    /// One section as an envelope part.
258	    fn section_part<'a>(&self, s: &'a Section) -> (Part<'a>, bool, Option<Hint>) {
259	        let total = s.shown_total();
260	        match &s.body {
261	            SectionBody::Toon { fields, rows } => match self.section_options(&s.name, fields, rows, total).validate() {
262	                Ok(doc) => {
263	                    let (text, cuts, extra) = doc.render_parts(false);
264	                    (Part { name: &s.name, text, cuts, total }, false, extra.map(Hint::new))
265	                }
266	                Err(e) => (Part::failed(&s.name, "toon_validation_failed", &e.to_string()), true, None),
267	            },
268	            SectionBody::Kv(items) => kv_part(&s.name, items, total),
269	            // One string value under the section's name, escaped like any other value: prose cannot start a line
270	            // of its own, so it cannot forge a `help[]` line or break the document.
271	            SectionBody::Text(text) => {
272	                let line = format!("{}: {}", crate::toon::escape_key(&s.name), crate::toon::escape_value(text));
273	                (Part { name: &s.name, text: line, cuts: Vec::new(), total }, false, None)
274	            }
275	        }
276	    }
