278	    /// Whether each block fails validation, without rendering it.
279	    fn failed_flags(&self) -> Vec<bool> {
280	        self.blocks()
281	            .iter()
282	            .map(|s| match &s.body {
283	                SectionBody::Toon { fields, rows } => {
284	                    self.section_options(&s.name, fields, rows, s.shown_total()).validate().is_err()
285	                }
286	                SectionBody::Kv(items) => crate::kv::validate_keys(items).is_err(),
287	                SectionBody::Text(_) => false,
288	            })
289	            .collect()
290	    }
291	
292	    /// The first root key two blocks of the body would both write, or `None`. Sections render as root keys (a TOON
293	    /// list or text section under its name, a KV section as its item keys), beside the keys michi writes itself:
294	    /// `budget`, its `sections` table, `provenance`, `truncated`, `totalCount`, `help`, `recovery`, and, for a block
295	    /// that failed validation, `error` and `message`. `failed[i]` says whether block `i` failed. The reserved names
296	    /// are claimed whether or not that block is present, so validity never depends on the caller's data. Provenance
297	    /// labels sit one level down and collide only with each other and the `fingerprint` line.
298	    fn root_collision(&self, failed: &[bool]) -> Option<String> {
299	        const RESERVED: [&str; 7] = ["budget", "sections", "provenance", "truncated", "totalCount", "help", "recovery"];
300	        let blocks = self.blocks();
301	        let mut seen: std::collections::HashSet<&str> = RESERVED.into_iter().collect();
302	        for (s, failed) in blocks.iter().zip(failed) {
303	            if *failed {
304	                for key in ["error", "message"] {
305	                    if !seen.insert(key) {
306	                        return Some(key.to_string());
307	                    }
308	                }
309	                continue;
310	            }
311	            let keys: Vec<&str> = match &s.body {
312	                SectionBody::Toon { .. } | SectionBody::Text(_) => vec![s.name.as_str()],
313	                SectionBody::Kv(items) => items.iter().map(|i| i.key.as_str()).collect(),
314	            };
315	            for key in keys {
316	                if !seen.insert(key) {
317	                    return Some(key.to_string());
318	                }
319	            }
320	        }
321	        let p = self.provenance.as_ref()?;
322	        let mut labels: std::collections::HashSet<&str> = std::collections::HashSet::new();
323	        if p.fingerprint.is_some() {
324	            labels.insert("fingerprint");
325	        }
326	        p.entries.iter().find(|e| !labels.insert(e.label.as_str())).map(|e| e.label.clone())
327	    }
328	
329	    /// The body: sections, `budget:`, `provenance:`.
330	    ///
331	    /// Blocks are joined with one LF and empty ones are skipped. `truncated` and `totalCount` are root keys, so they
332	    /// may appear once: when one block has them they stay inline after its list; when two or more do, each becomes
333	    /// one table with a leading `section` column, after the last block.
334	    ///
335	    /// The flag is whether this response is an error: set by `as_error()` or by a block that failed validation.
336	    /// Every output surface reads its error flag from here so text, JSON and MCP never disagree.
337	    fn body(&self) -> (String, bool, Vec<Hint>) {
338	        let blocks = self.blocks();
339	        let mut parts: Vec<Part<'_>> = Vec::with_capacity(blocks.len());
340	        let mut failed = false;
341	        let mut flags: Vec<bool> = Vec::with_capacity(blocks.len());
342	        let mut extras: Vec<Hint> = Vec::new();
343	        for s in blocks.iter() {
344	            let (part, part_failed, extra) = self.section_part(s);
345	            failed |= part_failed;
346	            flags.push(part_failed);
347	            // One line per cut response is enough: every section's line says the same thing.
348	            if let Some(h) = extra {
349	                if !extras.contains(&h) {
350	                    extras.push(h);
351	                }
352	            }
353	            parts.push(part);
354	        }
355	        // Two blocks writing one root key would be invalid TOON. Like any other bad input the whole body becomes the
356	        // visible validation error, so the caller sees it instead of a document a decoder rejects.
357	        if let Some(key) = self.root_collision(&flags) {
358	            return (collision_body(&key), true, Vec::new());
359	        }
360	        let cutters = parts.iter().filter(|p| !p.cuts.is_empty()).count();
361	        let totals = parts.iter().filter(|p| p.total.is_some()).count();
362	        let mut out = String::with_capacity(parts.iter().map(|p| p.text.len() + 24).sum::<usize>() + 256);
363	        for p in &parts {
364	            join_block(&mut out, &p.text);
365	            if cutters == 1 && !p.cuts.is_empty() {
366	                join_block(&mut out, &truncated_table(std::slice::from_ref(p)));
367	            }
368	            if let (1, Some(n)) = (totals, p.total) {
369	                join_block(&mut out, &format!("totalCount: {n}"));
370	            }
371	        }
372	        if cutters >= 2 {
373	            join_block(&mut out, &truncated_table(&parts));
374	        }
375	        if totals >= 2 {
376	            join_block(&mut out, &total_table(&parts));
377	        }
378	        if let Some(b) = &self.budget {
379	            join_block(&mut out, &crate::budget::render_budget_block(b, self.sections.len() >= 2));
380	        }
381	        if let Some(p) = &self.provenance {
382	            join_block(&mut out, &crate::provenance::render_provenance_block(p));
383	        }
384	        (out, failed || self.is_error, extras)
385	    }
386	
387	    /// Compose the text document: body, help block, recovery block. Each part is a TOON 4.4 document without a
388	    /// trailing newline and the append helpers join them with one LF, so the result is one root object whose keys
389	    /// are unique (the body cannot use `totalCount`, `help`, `recovery` or `truncated`). Appends to `body` in place.
390	    fn finish_text(&self, mut body: String, extra: &[Hint]) -> String {
391	        let hints = self.hints_with(extra);
392	        if !hints.is_empty() || !self.recovery.is_empty() {
393	            body.reserve(1 + hints.len() * 60 + self.recovery.len() * 80);
394	        }
395	        crate::hints::append_hints(&mut body, &hints);
396	        crate::recovery::append_recovery(&mut body, &self.recovery);
397	        body
398	    }
