414	    /// Whether this response is an error: `as_error()` was called, or a section's TOON rows or KV items failed
415	    /// validation and its block is a `toon_validation_failed` or `kv_validation_failed` error block. Validates
416	    /// without rendering.
417	    #[must_use]
418	    pub fn is_error(&self) -> bool {
419	        if self.is_error {
420	            return true;
421	        }
422	        let failed = self.failed_flags();
423	        failed.contains(&true) || self.root_collision(&failed).is_some()
424	    }
