449	    pub fn to_call_tool_result(&self) -> crate::mcp::CallToolResult {
450	        let (body, is_error, extra) = self.body();
451	        let structured_content = self.json_from_body(&body, is_error, &extra);
452	        let mut content = vec![crate::mcp::ContentBlock {
