470	    fn json_from_body(&self, body: &str, is_error: bool, extra: &[Hint]) -> String {
471	        let hints = self.hints_with(extra);
472	        let capacity =
473	            body.len() + hints.iter().map(|h| h.as_str().len() + 16).sum::<usize>() + self.recovery.len() * 64 + 64;
474	        let mut out = String::with_capacity(capacity + body.len() + 128);
475	        out.push_str("{\"body\":");
476	        json_string(&mut out, body);
477	        if !self.sections.is_empty() {
478	            out.push_str(",\"sections\":[");
479	            for (i, s) in self.sections.iter().enumerate() {
480	                if i > 0 {
481	                    out.push(',');
482	                }
483	                push_section_json(&mut out, s);
484	            }
485	            out.push(']');
486	        }
487	        if let Some(b) = &self.budget {
488	            out.push_str(",\"budget\":");
489	            out.push_str(&crate::budget::budget_json(b));
490	        }
491	        if let Some(p) = &self.provenance {
492	            out.push_str(",\"provenance\":");
493	            out.push_str(&crate::provenance::provenance_json(p));
494	        }
495	        out.push_str(",\"hints\":[");
496	        for (i, h) in hints.iter().enumerate() {
497	            if i > 0 {
498	                out.push(',');
499	            }
500	            json_string(&mut out, h.as_str());
501	        }
502	        out.push_str("],\"recovery\":[");
503	        for (i, r) in self.recovery.iter().enumerate() {
504	            if i > 0 {
505	                out.push(',');
506	            }
507	            out.push_str("{\"tool\":");
508	            json_string(&mut out, &r.tool);
509	            out.push_str(",\"params\":");
510	            crate::recovery::push_params_json(&mut out, &r.params);
511	            if let Some(reason) = &r.reason {
512	                out.push_str(",\"reason\":");
513	                json_string(&mut out, reason);
514	            }
515	            out.push('}');
516	        }
517	        out.push_str("],\"isError\":");
518	        out.push_str(if is_error { "true" } else { "false" });
519	        out.push('}');
520	        out
521	    }
522	}
