524	/// The body that replaces rows or items that cannot form a valid document: `error: <code>` and the quoted message.
525	fn validation_error_body(code: &str, message: &str) -> String {
526	    let message = crate::toon::escape_value(message);
527	    let mut out = String::with_capacity(17 + code.len() + message.len());
528	    out.push_str("error: ");
529	    out.push_str(code);
530	    out.push_str("\nmessage: ");
531	    out.push_str(&message);
532	    out
533	}
534	
535	/// The body for two blocks that would write the same root key.
536	fn collision_body(key: &str) -> String {
537	    validation_error_body(
538	        "toon_validation_failed",
539	        &format!("duplicate root key '{key}': give every section and KV key a distinct name"),
540	    )
541	}
