543	/// One block of an envelope body before the root-level `truncated` and `totalCount` keys are placed.
544	struct Part<'a> {
545	    /// The block's name, the `section` column when several blocks share a root key.
546	    name: &'a str,
547	    /// The block's text without its `truncated` block or `totalCount` line.
548	    text: String,
549	    /// Cut cells as `(row, field name, chars removed)`.
550	    cuts: Vec<(usize, String, usize)>,
551	    /// The `totalCount` this block reports, when it reports one.
552	    total: Option<usize>,
553	}
554	
555	impl<'a> Part<'a> {
556	    /// A block that failed validation: the error body replaces its content and it reports no count.
557	    fn failed(name: &'a str, code: &str, message: &str) -> Self {
558	        Self { name, text: validation_error_body(code, message), cuts: Vec::new(), total: None }
559	    }
560	}
561	
562	/// A KV block as a part. No items still reports a larger total the caller set.
563	fn kv_part<'a>(name: &'a str, items: &[KvItem], total: Option<usize>) -> (Part<'a>, bool, Option<Hint>) {
564	    if items.is_empty() {
565	        return (Part { name, text: String::new(), cuts: Vec::new(), total }, false, None);
566	    }
567	    match crate::kv::render_kv(items, None, &[]) {
568	        Ok(text) => (Part { name, text, cuts: Vec::new(), total }, false, None),
569	        Err(e) => (Part::failed(name, "kv_validation_failed", &e.to_string()), true, None),
570	    }
571	}
572	
573	/// Append `block` after a LF unless either side is empty.
574	fn join_block(out: &mut String, block: &str) {
575	    if block.is_empty() {
576	        return;
577	    }
578	    if !out.is_empty() {
579	        out.push('\n');
580	    }
581	    out.push_str(block);
582	}
583	
584	/// The `truncated` block for the cuts of `parts`. A single block uses the inline shape
585	/// (`{row,field,removed}`); several share one table with a leading `section` column.
586	fn truncated_table(parts: &[Part<'_>]) -> String {
587	    use std::fmt::Write as _;
588	    let n: usize = parts.iter().map(|p| p.cuts.len()).sum();
589	    let mut out = String::with_capacity(48 + n * 32);
590	    let multi = parts.iter().filter(|p| !p.cuts.is_empty()).count() > 1;
591	    let _ = write!(out, "truncated[{n}]{}:", if multi { "{section,row,field,removed}" } else { "{row,field,removed}" });
592	    for p in parts {
593	        for (row, field, removed) in &p.cuts {
594	            out.push_str("\n  ");
595	            if multi {
596	                out.push_str(&crate::toon::escape_value(p.name));
597	                out.push(',');
598	            }
599	            let _ = write!(out, "{row},{},{removed}", crate::toon::escape_value(field));
600	        }
601	    }
602	    out
603	}
604	
605	/// The merged `totalCount[N]{section,total}:` table, for two or more blocks that report a total.
606	fn total_table(parts: &[Part<'_>]) -> String {
607	    use std::fmt::Write as _;
608	    let n = parts.iter().filter(|p| p.total.is_some()).count();
609	    let mut out = String::with_capacity(32 + n * 24);
610	    let _ = write!(out, "totalCount[{n}]{{section,total}}:");
611	    for p in parts {
612	        if let Some(total) = p.total {
613	            let _ = write!(out, "\n  {},{total}", crate::toon::escape_value(p.name));
614	        }
615	    }
616	    out
617	}
618	
619	/// A TOON cell value as JSON. Non-finite floats are `null`, as in the text render.
620	fn push_value_json(out: &mut String, v: &Value) {
621	    use std::fmt::Write as _;
622	    match v {
623	        Value::Str(s) => json_string(out, s),
624	        Value::Int(n) => {
625	            let _ = write!(out, "{n}");
626	        }
627	        Value::UInt(n) => {
628	            let _ = write!(out, "{n}");
629	        }
630	        Value::Float(f) => crate::toon::push_f64(out, *f),
631	        Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
632	        _ => out.push_str("null"),
633	    }
634	}
635	
636	/// One section as the JSON object spec 07 section 5 describes. Rows carry the full values: the per-cell cap shapes
637	/// the text render, and `structuredContent` is the typed copy of the same data.
638	fn push_section_json(out: &mut String, s: &Section) {
639	    use std::fmt::Write as _;
640	    out.push_str("{\"name\":");
641	    json_string(out, &s.name);
642	    match &s.body {
643	        SectionBody::Toon { fields, rows } => {
644	            out.push_str(",\"kind\":\"toon\",\"fields\":[");
645	            for (i, f) in fields.iter().enumerate() {
646	                if i > 0 {
647	                    out.push(',');
648	                }
649	                json_string(out, f);
650	            }
651	            out.push_str("],\"rows\":[");
652	            for (i, row) in rows.iter().enumerate() {
653	                if i > 0 {
654	                    out.push(',');
655	                }
656	                out.push('[');
657	                for (j, cell) in row.iter().enumerate() {
658	                    if j > 0 {
659	                        out.push(',');
660	                    }
661	                    push_value_json(out, cell);
662	                }
663	                out.push(']');
664	            }
665	            out.push(']');
666	        }
667	        SectionBody::Kv(items) => {
668	            out.push_str(",\"kind\":\"kv\",\"items\":[");
669	            for (i, item) in items.iter().enumerate() {
670	                if i > 0 {
671	                    out.push(',');
672	                }
673	                out.push_str("{\"key\":");
674	                json_string(out, &item.key);
675	                out.push_str(",\"value\":");
676	                crate::kv::kv_value_to_json(out, &item.value);
677	                out.push('}');
678	            }
679	            out.push(']');
680	        }
681	        SectionBody::Text(text) => {
682	            out.push_str(",\"kind\":\"text\",\"text\":");
683	            json_string(out, text);
684	        }
685	    }
686	    let _ = write!(out, ",\"returnedCount\":{}", s.count());
687	    if let Some(total) = s.total_count {
688	        let _ = write!(out, ",\"totalCount\":{total}");
689	    }
690	    out.push_str(",\"truncated\":");
691	    out.push_str(if s.truncated { "true" } else { "false" });
692	    out.push('}');
693	}
694	
695	fn json_string(out: &mut String, s: &str) {
696	    crate::kv::json_escape_str(out, s);
697	}
