1183	        assert!(raw.contains(r"\u0001"), "got: {raw}");
1184	        let parsed: serde_json::Value = serde_json::from_str(&raw).expect("must be valid JSON");
1185	        assert_eq!(parsed["hints"][0].as_str().unwrap(), "before\u{1}after");
1186	    }
1187	
1188	    // AC-049: DEFAULT_TRUNCATE_CELLS is a public constant equal to 200.
1189	    #[test]
1190	    fn ac049_default_truncate_cells_is_200() {
1191	        assert_eq!(DEFAULT_TRUNCATE_CELLS, 200);
1192	    }
1193	
1194	    // AC-050: without an explicit .truncate_cells_at() call, the default
1195	    // (200) boundary holds: 199 chars untruncated, 250 chars truncated.
1196	    #[test]
1197	    fn ac050_default_truncate_boundary_holds_without_explicit_call() {
1198	        let untruncated = AgentResponse::new("t").items(vec![vec![Value::from("x".repeat(199))]], &["c"]);
1199	        let out = untruncated.render(OutputFormat::Text);
1200	        let cell_line = out.lines().nth(1).expect("row line present");
1201	        assert!(cell_line.contains(&"x".repeat(199)), "199 chars must be untruncated, got: {cell_line:?}");
1202	
1203	        let truncated = AgentResponse::new("t").items(vec![vec![Value::from("x".repeat(250))]], &["c"]);
1204	        let out = truncated.render(OutputFormat::Text);
1205	        let cell_line = out.lines().nth(1).expect("row line present");
1206	        let value_part = cell_line.trim_start();
1207	        assert!(
1208	            value_part.chars().count() <= DEFAULT_TRUNCATE_CELLS,
1209	            "got line with {} chars: {cell_line:?}",
1210	            value_part.chars().count()
1211	        );
1212	    }
1213	
1214	    #[test]
1215	    fn has_human_content_false_when_empty() {
1216	        let r = AgentResponse::new("items");
1217	        assert!(!r.has_human_content());
1218	    }
