1	//! Response-level budget report: what ceilings a caller worked under, what the response cost, and what each section
2	//! cost. michi renders a budget; it never computes one. See `docs/spec/07-wisp-and-monokl-envelope.md` §2.
3	
4	use std::fmt::Write as _;
5	
6	/// What a budget block renders: the ceilings a caller was working under, what the response cost against them, and
7	/// what that cost each section.
8	///
9	/// Every number is optional, so a caller who measured only tokens sets two fields and leaves the rest empty. Absent
10	/// fields are omitted from the rendered block, never written as `null`. `u64` rather than `usize` because these
11	/// values reach JSON, where a platform-dependent width means nothing.
12	///
13	/// `#[non_exhaustive]`: start from [`BudgetSummary::new`] or `Default` and use the builder methods.
14	///
15	/// # Stability
16	///
17	/// Part of the multi-section envelope, which is unstable until a second independent consumer has used it (ADR 10).
18	/// Its shape may change before 1.0.
19	#[derive(Debug, Clone, Default, PartialEq, Eq)]
20	#[cfg_attr(feature = "serde", derive(serde::Serialize))]
21	#[cfg_attr(feature = "serde", serde(rename_all = "camelCase"))]
22	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
23	#[cfg_attr(feature = "schemars", schemars(rename_all = "camelCase"))]
24	#[non_exhaustive]
25	pub struct BudgetSummary {
26	    /// Token ceiling the caller set.
27	    #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
28	    pub max_tokens: Option<u64>,
29	    /// Byte ceiling the caller set.
30	    #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
31	    pub max_bytes: Option<u64>,
32	    /// Item ceiling the caller set.
33	    #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
34	    pub max_items: Option<u64>,
35	    /// Tokens the response cost, as the caller measured it.
36	    #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
37	    pub tokens_used: Option<u64>,
38	    /// Bytes the response cost, as the caller measured it.
39	    #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
40	    pub bytes_used: Option<u64>,
41	    /// Whether the budget forced anything out of the response.
42	    pub truncated: bool,
43	    /// Per-section accounting, rendered in the order given.
44	    pub sections: Vec<SectionCost>,
45	}
46	
47	impl BudgetSummary {
48	    /// An empty summary: no ceilings, no measurements, not truncated, no sections.
49	    #[must_use]
50	    pub fn new() -> Self {
51	        Self::default()
52	    }
53	
54	    /// Set the token ceiling.
55	    #[must_use]
56	    pub fn max_tokens(mut self, n: u64) -> Self {
57	        self.max_tokens = Some(n);
58	        self
59	    }
60	
61	    /// Set the byte ceiling.
62	    #[must_use]
63	    pub fn max_bytes(mut self, n: u64) -> Self {
64	        self.max_bytes = Some(n);
65	        self
66	    }
67	
68	    /// Set the item ceiling.
69	    #[must_use]
70	    pub fn max_items(mut self, n: u64) -> Self {
71	        self.max_items = Some(n);
72	        self
73	    }
74	
75	    /// Set the tokens the response cost.
76	    #[must_use]
77	    pub fn tokens_used(mut self, n: u64) -> Self {
78	        self.tokens_used = Some(n);
79	        self
80	    }
81	
82	    /// Set the bytes the response cost.
83	    #[must_use]
84	    pub fn bytes_used(mut self, n: u64) -> Self {
85	        self.bytes_used = Some(n);
86	        self
87	    }
88	
89	    /// Set whether the budget forced anything out of the response.
90	    #[must_use]
91	    pub fn truncated(mut self, truncated: bool) -> Self {
92	        self.truncated = truncated;
93	        self
94	    }
95	
96	    /// Append one section's accounting line. Lines render in the order added.
97	    #[must_use]
98	    pub fn section(mut self, cost: SectionCost) -> Self {
99	        self.sections.push(cost);
100	        self
101	    }
102	}
103	
104	/// One section's line in the budget roll-up.
105	///
106	/// `#[non_exhaustive]`: build it with [`SectionCost::new`] and the builder methods.
107	#[derive(Debug, Clone, PartialEq, Eq)]
108	#[cfg_attr(feature = "serde", derive(serde::Serialize))]
109	#[cfg_attr(feature = "serde", serde(rename_all = "camelCase"))]
110	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
111	#[cfg_attr(feature = "schemars", schemars(rename_all = "camelCase"))]
112	#[non_exhaustive]
113	pub struct SectionCost {
114	    /// The section's name.
115	    pub name: String,
116	    /// How many items the section returned.
117	    pub returned: u64,
118	    /// How many existed before truncation, when the caller knows.
119	    #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
120	    pub total: Option<u64>,
121	    /// Whether this section was cut.
122	    pub truncated: bool,
123	}
124	
125	impl SectionCost {
126	    /// A section line with no known total, not truncated.
127	    #[must_use]
128	    pub fn new(name: impl Into<String>, returned: u64) -> Self {
129	        Self { name: name.into(), returned, total: None, truncated: false }
130	    }
131	
132	    /// Set how many items existed before truncation.
133	    #[must_use]
134	    pub fn total(mut self, total: u64) -> Self {
135	        self.total = Some(total);
136	        self
137	    }
138	
139	    /// Set whether this section was cut.
140	    #[must_use]
141	    pub fn truncated(mut self, truncated: bool) -> Self {
142	        self.truncated = truncated;
143	        self
144	    }
145	}
146	
147	/// Render the `budget:` block, with no trailing newline. When `show_rollup` is set and there are sections, the
148	/// `sections[n]{name,returned,total,truncated}:` table follows. An unknown `total` is the TOON `null` cell, because a
149	/// table row needs a value in every column.
150	pub(crate) fn render_budget_block(b: &BudgetSummary, show_rollup: bool) -> String {
151	    let mut out = String::with_capacity(160 + b.sections.len() * 48);
152	    out.push_str("budget:");
153	    for (key, value) in numbers(b) {
154	        if let Some(n) = value {
155	            let _ = write!(out, "\n  {key}: {n}");
156	        }
157	    }
158	    let _ = write!(out, "\n  truncated: {}", b.truncated);
159	    if show_rollup && !b.sections.is_empty() {
160	        let _ = write!(out, "\nsections[{}]{{name,returned,total,truncated}}:", b.sections.len());
161	        for s in &b.sections {
162	            let _ = write!(out, "\n  {},{},", crate::toon::escape_value(&s.name), s.returned);
163	            match s.total {
164	                Some(t) => {
165	                    let _ = write!(out, "{t}");
166	                }
167	                None => out.push_str("null"),
168	            }
169	            let _ = write!(out, ",{}", s.truncated);
170	        }
171	    }
172	    out
173	}
174	
175	/// The optional counters in render order.
176	fn numbers(b: &BudgetSummary) -> [(&'static str, Option<u64>); 5] {
177	    [
178	        ("tokensUsed", b.tokens_used),
179	        ("bytesUsed", b.bytes_used),
180	        ("maxTokens", b.max_tokens),
181	        ("maxBytes", b.max_bytes),
182	        ("maxItems", b.max_items),
183	    ]
184	}
185	
186	/// The budget as a JSON object with camelCase keys. `sections` is always present; absent numbers are omitted.
187	pub(crate) fn budget_json(b: &BudgetSummary) -> String {
188	    let mut out = String::with_capacity(128 + b.sections.len() * 64);
189	    out.push('{');
190	    for (key, value) in numbers(b) {
191	        if let Some(n) = value {
192	            let _ = write!(out, "\"{key}\":{n},");
193	        }
194	    }
195	    let _ = write!(out, "\"truncated\":{},\"sections\":[", b.truncated);
196	    for (i, s) in b.sections.iter().enumerate() {
197	        if i > 0 {
198	            out.push(',');
199	        }
200	        out.push_str("{\"name\":");
201	        crate::kv::json_escape_str(&mut out, &s.name);
202	        let _ = write!(out, ",\"returned\":{}", s.returned);
203	        if let Some(t) = s.total {
204	            let _ = write!(out, ",\"total\":{t}");
205	        }
206	        let _ = write!(out, ",\"truncated\":{}}}", s.truncated);
207	    }
208	    out.push_str("]}");
209	    out
210	}
211	
212	#[cfg(test)]
213	mod tests {
214	    use super::*;
215	
216	    fn spec_example() -> BudgetSummary {
217	        BudgetSummary::new()
218	            .tokens_used(7412)
219	            .bytes_used(31208)
220	            .max_tokens(8000)
221	            .max_bytes(2_097_152)
222	            .truncated(true)
223	            .section(SectionCost::new("brief.symbols", 12).total(40).truncated(true))
224	            .section(SectionCost::new("brief.refs", 5).total(5))
225	    }
226	
227	    const SPEC_BLOCK: &str =
228	        "budget:\n  tokensUsed: 7412\n  bytesUsed: 31208\n  maxTokens: 8000\n  maxBytes: 2097152\n  truncated: true";
229	    const SPEC_ROLLUP: &str =
230	        "\nsections[2]{name,returned,total,truncated}:\n  brief.symbols,12,40,true\n  brief.refs,5,5,false";
231	
232	    #[test]
233	    fn spec_example_renders_exactly_with_rollup() {
234	        assert_eq!(render_budget_block(&spec_example(), true), format!("{SPEC_BLOCK}{SPEC_ROLLUP}"));
235	    }
236	
237	    #[test]
238	    fn rollup_only_when_requested() {
239	        assert_eq!(render_budget_block(&spec_example(), false), SPEC_BLOCK);
240	    }
241	
242	    #[test]
243	    fn absent_fields_are_omitted_not_null() {
244	        let b = BudgetSummary::new().tokens_used(10).max_items(3);
245	        let out = render_budget_block(&b, true);
246	        assert_eq!(out, "budget:\n  tokensUsed: 10\n  maxItems: 3\n  truncated: false");
247	        assert!(!out.contains("null"));
248	        assert_eq!(render_budget_block(&BudgetSummary::new(), true), "budget:\n  truncated: false");
249	    }
250	
251	    #[test]
252	    fn unknown_total_is_a_null_cell_and_hostile_names_are_quoted() {
253	        let b = BudgetSummary::new().section(SectionCost::new("a,b\nbudget: x", 1));
254	        let out = render_budget_block(&b, true);
255	        assert_eq!(
256	            out,
257	            "budget:\n  truncated: false\nsections[1]{name,returned,total,truncated}:\n  \"a,b\\nbudget: x\",1,null,false"
258	        );
259	        assert_eq!(out.lines().count(), 4, "no fake lines");
260	    }
261	
262	    #[test]
263	    fn json_matches_spec_shape() {
264	        assert_eq!(
265	            budget_json(&spec_example()),
266	            "{\"tokensUsed\":7412,\"bytesUsed\":31208,\"maxTokens\":8000,\"maxBytes\":2097152,\"truncated\":true,\
267	             \"sections\":[{\"name\":\"brief.symbols\",\"returned\":12,\"total\":40,\"truncated\":true},\
268	             {\"name\":\"brief.refs\",\"returned\":5,\"total\":5,\"truncated\":false}]}"
269	        );
270	        assert_eq!(budget_json(&BudgetSummary::new()), "{\"truncated\":false,\"sections\":[]}");
271	        let b = BudgetSummary::new().section(SectionCost::new("x", 1));
272	        assert_eq!(
273	            budget_json(&b),
274	            "{\"truncated\":false,\"sections\":[{\"name\":\"x\",\"returned\":1,\"truncated\":false}]}"
275	        );
276	    }
277	
278	    #[cfg(feature = "serde")]
279	    #[test]
280	    fn hand_built_json_parses_and_matches_serde() {
281	        let hostile = BudgetSummary::new()
282	            .max_tokens(1)
283	            .section(SectionCost::new("q\"uote\\\n\u{1}", 2).total(3))
284	            .section(SectionCost::new("plain", 0));
285	        for b in [spec_example(), hostile, BudgetSummary::new()] {
286	            let hand: serde_json::Value = serde_json::from_str(&budget_json(&b)).expect("valid json");
287	            let derived = serde_json::to_value(&b).expect("serializes");
288	            assert_eq!(hand, derived);
289	        }
290	    }
291	
292	    #[cfg(feature = "schemars")]
293	    #[test]
294	    fn schema_uses_camel_case() {
295	        let schema = serde_json::to_string(&schemars::schema_for!(BudgetSummary)).expect("schema");
296	        for key in ["maxTokens", "tokensUsed", "bytesUsed", "maxItems", "returned"] {
297	            assert!(schema.contains(key), "{key} missing from {schema}");
298	        }
299	        assert!(!schema.contains("tokens_used"));
300	    }
301	}
