5	/// A single key-value pair for [`render_kv`].
6	///
7	/// `#[non_exhaustive]`: build it with [`KvItem::new`]; the fields stay public.
8	#[derive(Debug, Clone, PartialEq)]
9	#[non_exhaustive]
10	pub struct KvItem {
11	    /// The field name.
12	    pub key: String,
13	    /// The field value.
14	    pub value: KvValue,
15	}
16	
17	impl KvItem {
18	    /// A key-value pair.
19	    #[must_use]
20	    pub fn new(key: impl Into<String>, value: KvValue) -> Self {
21	        Self { key: key.into(), value }
22	    }
23	}
