25	/// A value in a key-value item, rendered as a TOON 4.4 primitive.
26	///
27	/// `#[non_exhaustive]`: new value kinds may be added in a minor release, so a `match` outside michi needs a wildcard
28	/// arm.
29	#[derive(Debug, Clone, PartialEq)]
30	#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
31	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
32	#[non_exhaustive]
33	pub enum KvValue {
34	    /// UTF-8 text value, quoted only when TOON 4.4 §7.2 requires it.
35	    Text(String),
36	    /// Signed integer.
37	    Int(#[cfg_attr(feature = "schemars", schemars(schema_with = "crate::int_schema::i64"))] i64),
38	    /// Floating-point number, rounded to the given number of decimal places and then written in canonical TOON
39	    /// number form (§2): the decimals bound the precision but never pad (`Float(1.5, 3)` renders `1.5`).
40	    /// [`KvValue::FULL_PRECISION`] (255) never rounds: the value renders with its shortest round-trip digits, so even
41	    /// `5e-324` keeps its value. Any smaller count rounds as asked, so `Float(1e-300, 2)` renders `0`.
42	    ///
43	    /// NaN and ±Infinity render as `null` in every rendered output, TOON (§3) and the JSON companions alike. With
44	    /// the `serde` feature, `KvValue` itself serializes a non-finite float as the string `"NaN"`, `"Infinity"` or
45	    /// `"-Infinity"` (finite values stay JSON numbers) and accepts those strings back, so it round-trips exactly.
46	    Float(
47	        #[cfg_attr(feature = "serde", serde(with = "crate::float_wire"))]
48	        #[cfg_attr(feature = "schemars", schemars(schema_with = "crate::float_wire::schema"))]
49	        f64,
50	        #[cfg_attr(feature = "schemars", schemars(schema_with = "crate::int_schema::u8"))] u8,
51	    ),
52	    /// Boolean renders as `true` or `false`.
53	    Bool(bool),
54	    /// Elapsed time, rendered as the string of fractional seconds with one decimal, e.g. `1.5s`.
55	    Duration(Duration),
56	    /// Absent value, renders as `null`.
57	    Missing,
58	}
59	
60	impl KvValue {
61	    /// The decimals setting of [`KvValue::Float`] that never rounds: the float renders with its shortest round-trip
62	    /// digits, in exponent form when TOON's canonical number form calls for it (`1e-300`). Use it when the value
63	    /// itself matters more than a fixed precision. It is `u8::MAX`, so a count this large meant the same thing for
64	    /// every value that 255 places could already hold.
65	    pub const FULL_PRECISION: u8 = u8::MAX;
66	}
67	
68	/// Append a KV value as a TOON 4.4 primitive token (§2, §3, §7.2).
69	///
70	/// `Text` is quoted only when §7.2 requires it (line breaks become `\n`/`\r` inside quotes); `Int` and `Bool` are
71	/// literal; `Float(f, decimals)` is rounded to `decimals` places and the rounded value is written in canonical number
72	/// form; `Duration` is the string `{secs:.1}s`; `Missing` is `null`.
73	pub(crate) fn push_kv_value(out: &mut String, value: &KvValue) {
74	    match value {
75	        KvValue::Text(s) => out.push_str(&crate::toon::escape_value(s)),
76	        KvValue::Int(n) => {
77	            let _ = write!(out, "{n}");
78	        }
79	        KvValue::Float(f, decimals) => crate::toon::push_f64(out, round_to_decimals(*f, *decimals)),
80	        KvValue::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
81	        KvValue::Duration(d) => {
82	            let mut secs = String::with_capacity(16);
83	            let _ = write!(secs, "{:.1}s", d.as_secs_f64());
84	            out.push_str(&crate::toon::escape_value(&secs));
85	        }
86	        KvValue::Missing => out.push_str("null"),
87	    }
88	}
89	
90	/// The decimal places `KvValue::Float` needs to reproduce `f` exactly: the fractional digits of its shortest exact
91	/// representation (Rust's `Display` for f64, which never uses an exponent), so `1e-7` needs 7 and `2.0` needs 0.
92	/// Non-finite values need 0. A value needing more than 254 places gets [`KvValue::FULL_PRECISION`], which never
93	/// rounds. Used where a float arrives without a decimals setting.
94	#[cfg(any(feature = "serde", feature = "napi"))]
95	pub(crate) fn exact_decimals(f: f64) -> u8 {
96	    if !f.is_finite() {
97	        return 0;
98	    }
99	    let places = f.to_string().split_once('.').map_or(0, |(_, frac)| frac.len());
100	    u8::try_from(places).unwrap_or(KvValue::FULL_PRECISION)
101	}
102	
103	/// `f` rounded to `decimals` fractional digits by the correctly rounded decimal formatting of `{f:.decimals}`.
104	/// Non-finite values, and every value at [`KvValue::FULL_PRECISION`], pass through unchanged.
105	fn round_to_decimals(f: f64, decimals: u8) -> f64 {
106	    if !f.is_finite() || decimals == KvValue::FULL_PRECISION {
107	        return f;
108	    }
109	    format!("{f:.*}", usize::from(decimals)).parse().unwrap_or(f)
110	}
111	
112	pub(crate) fn json_escape_str(out: &mut String, s: &str) {
113	    out.push('"');
114	    for ch in s.chars() {
115	        match ch {
116	            '"' => out.push_str("\\\""),
117	            '\\' => out.push_str("\\\\"),
118	            '\n' => out.push_str("\\n"),
119	            '\r' => out.push_str("\\r"),
120	            '\t' => out.push_str("\\t"),
121	            other if u32::from(other) < 0x20 => {
122	                let code = u32::from(other);
123	                out.push_str("\\u00");
124	                out.push(char::from_digit(code >> 4, 16).unwrap_or('0'));
125	                out.push(char::from_digit(code & 0xf, 16).unwrap_or('0'));
126	            }
127	            other => out.push(other),
128	        }
129	    }
130	    out.push('"');
131	}
132	
133	pub(crate) fn kv_value_to_json(out: &mut String, value: &KvValue) {
134	    match value {
135	        KvValue::Text(s) => json_escape_str(out, s),
136	        KvValue::Int(n) => {
137	            let _ = write!(out, "{n}");
138	        }
139	        KvValue::Float(f, decimals) => {
140	            if !f.is_finite() {
141	                // Not a JSON number: `null`, the same token the TOON body uses (§3), so the surfaces agree.
142	                out.push_str("null");
143	            } else if *decimals == KvValue::FULL_PRECISION {
144	                // TOON's canonical number form is also valid JSON (`1e-300`, `1e+21`), and padding to 255 places
145	                // would round a smaller value to zero.
146	                crate::toon::push_f64(out, *f);
147	            } else {
148	                let _ = write!(out, "{f:.*}", *decimals as usize);
149	            }
150	        }
151	        KvValue::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
152	        KvValue::Duration(d) => {
153	            let mut secs = String::new();
154	            let _ = write!(secs, "{:.1}s", d.as_secs_f64());
155	            json_escape_str(out, &secs);
156	        }
157	        KvValue::Missing => out.push_str("null"),
158	    }
159	}
