161	/// Root keys michi composes next to a body (a TOON list's type entry or KV items), so a body may not use them: the
162	/// document would otherwise hold a duplicate key, which TOON 4.4 §14.3 forbids.
163	pub(crate) const RESERVED_ROOT_KEYS: [&str; 3] = ["totalCount", "help", "recovery"];
164	
165	/// Error returned by [`render_kv`] when the items cannot form a valid TOON document.
166	#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
167	#[non_exhaustive]
168	pub enum KvError {
169	    /// An item key is a root key michi composes next to the items (`totalCount`, `help` or `recovery`). It is
170	    /// rejected whether or not that key is present in this document, so validity never depends on the data.
171	    #[error("key {key:?} is a reserved document key (totalCount, help, recovery)")]
172	    ReservedKey {
173	        /// The offending key.
174	        key: String,
175	    },
176	    /// Two items share a key; a TOON object may not repeat a key (§14.3).
177	    #[error("key {key:?} appears more than once")]
178	    DuplicateKey {
179	        /// The offending key.
180	        key: String,
181	    },
182	}
183	
184	/// Check that `items` can be the fields of a TOON root object next to michi's reserved keys.
185	pub(crate) fn validate_keys(items: &[KvItem]) -> Result<(), KvError> {
186	    let mut seen = std::collections::HashSet::with_capacity(items.len());
187	    for item in items {
188	        if RESERVED_ROOT_KEYS.contains(&item.key.as_str()) {
189	            return Err(KvError::ReservedKey { key: item.key.clone() });
190	        }
191	        if !seen.insert(item.key.as_str()) {
192	            return Err(KvError::DuplicateKey { key: item.key.clone() });
193	        }
194	    }
195	    Ok(())
196	}
197	
198	/// Append one `key: value` line (§8), preceded by a LF when `out` is non-empty and does not already end in one.
199	pub(crate) fn push_kv_line(out: &mut String, key: &str, value: &KvValue) {
200	    if !out.is_empty() && !out.ends_with('\n') {
201	        out.push('\n');
202	    }
203	    out.push_str(&crate::toon::escape_key(key));
204	    out.push_str(": ");
205	    push_kv_value(out, value);
206	}
207	
208	/// Render key-value pairs as a TOON 4.4 root object (§8): one `key: value` line per item, then `totalCount: N` and
209	/// the inline `help[N]: …` array when present, with no trailing newline.
210	///
211	/// Keys are quoted per §7.3 and values written as TOON primitives (see [`KvValue`]). Exactly one space follows each
212	/// colon, so values are not column-aligned. Returns the empty string (the empty TOON document) for empty `items`,
213	/// ignoring `total_count` and `hints`.
214	///
215	/// # Errors
216	///
217	/// [`KvError::ReservedKey`] for an item key `totalCount`, `help` or `recovery`, and [`KvError::DuplicateKey`] for a
218	/// repeated key: either would make the document hold a duplicate key (§14.3).
219	pub fn render_kv(items: &[KvItem], total_count: Option<usize>, hints: &[Hint]) -> Result<String, KvError> {
220	    if items.is_empty() {
221	        return Ok(String::new());
222	    }
223	    validate_keys(items)?;
224	    let capacity = items.iter().map(|i| i.key.len() + 24).sum::<usize>() + hints.len() * 50 + 20;
225	    let mut out = String::with_capacity(capacity);
226	    for item in items {
227	        push_kv_line(&mut out, &item.key, &item.value);
228	    }
229	    if let Some(total) = total_count {
230	        out.push_str("\ntotalCount: ");
231	        let _ = write!(out, "{total}");
232	    }
233	    crate::hints::append_hints(&mut out, hints);
234	    Ok(out)
235	}
