168	/// Cut `s` to at most `max_cell_len` chars: `max_cell_len - 1` kept chars and a plain `…`, or the empty string for a
169	/// cap of 0. Returns the cell and the number of chars cut off, or `None` when `s` fits. The cell never carries a
170	/// message: the cut is reported in the `truncated` block (see `push_truncated`).
171	fn cut_cell(s: &str, max_cell_len: usize) -> Option<(String, usize)> {
172	    // Byte length is always >= char count, so a string that fits in bytes fits in chars: skip the UTF-8 scan.
173	    if s.len() <= max_cell_len {
174	        return None;
175	    }
176	    let total = s.chars().count();
177	    if total <= max_cell_len {
178	        return None;
179	    }
180	    let keep = max_cell_len.saturating_sub(1);
181	    let end = s.char_indices().nth(keep).map_or(s.len(), |(i, _)| i);
182	    let mut cell = String::with_capacity(end + 3);
183	    cell.push_str(&s[..end]);
184	    if max_cell_len > 0 {
185	        cell.push('\u{2026}');
186	    }
187	    Some((cell, total - keep))
188	}
