190	/// Append one row cell: §7.2 quoting for strings, §2/§3 canonical numbers, the `null` literal. Only strings are cut
191	/// to `max_cell_len` chars, counted before escaping. Returns the chars cut off a string, `None` when the cell is whole.
192	fn push_cell(out: &mut String, cell: &Value, max_cell_len: usize) -> Option<usize> {
193	    use std::fmt::Write as _;
194	    match cell {
195	        Value::Str(s) => {
196	            if let Some((cut, removed)) = cut_cell(s, max_cell_len) {
197	                out.push_str(&escape_value(&cut));
198	                return Some(removed);
199	            }
200	            out.push_str(&escape_value(s));
201	        }
202	        Value::Int(n) => {
203	            let _ = write!(out, "{n}");
204	        }
205	        Value::UInt(n) => {
206	            let _ = write!(out, "{n}");
207	        }
208	        Value::Float(f) => push_f64(out, *f),
209	        Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
210	        Value::Null => out.push_str("null"),
211	    }
212	    None
213	}
