215	/// Append the list entry in the form TOON 4.4 prescribes for its shape, each line ending in a newline:
216	/// - no rows: `key: []` (§9.1; the field list is not emitted, an empty array has no shape),
217	/// - rows with zero fields: `key[N]:` and N bare `-` items, since empty objects may not use tabular form
218	///   (§9.3, §9.4, §10),
219	/// - otherwise the tabular form `key[N]{f1,f2}:` with one row per line at depth 1 (§9.3).
220	///
221	/// Returns the cells that were cut, as `(row, field index, chars removed)`.
222	fn push_list(out: &mut String, opts: &crate::toon::ToonOptions) -> Vec<(usize, usize, usize)> {
223	    use std::fmt::Write as _;
224	    let mut cut = Vec::new();
225	    out.push_str(&escape_key(&opts.type_name));
226	    if opts.rows.is_empty() {
227	        out.push_str(": []\n");
228	        return cut;
229	    }
230	    let _ = write!(out, "[{}]", opts.rows.len());
231	    if opts.fields.is_empty() {
232	        out.push_str(":\n");
233	        for _ in &opts.rows {
234	            out.push_str("  -\n");
235	        }
236	        return cut;
237	    }
238	    out.push('{');
239	    for (i, field) in opts.fields.iter().enumerate() {
240	        if i > 0 {
241	            out.push(',');
242	        }
243	        out.push_str(&escape_key(field));
244	    }
245	    out.push_str("}:\n");
246	    for (r, row) in opts.rows.iter().enumerate() {
247	        out.push_str("  ");
248	        for (i, cell) in row.iter().enumerate() {
249	            if i > 0 {
250	                out.push(',');
251	            }
252	            if let Some(removed) = push_cell(out, cell, opts.max_cell_len) {
253	                cut.push((r, i, removed));
254	            }
255	        }
256	        out.push('\n');
257	    }
258	    cut
259	}
