261	/// Append the `truncated[N]{row,field,removed}:` block that reports every cut cell (nothing when none was cut). It is
262	/// michi's own signal: cell text is quoted and escaped, so no cell can produce this block or one of its rows.
263	fn push_truncated(out: &mut String, opts: &crate::toon::ToonOptions, cut: &[(usize, usize, usize)]) {
264	    use std::fmt::Write as _;
265	    if cut.is_empty() {
266	        return;
267	    }
268	    let _ = writeln!(out, "truncated[{}]{{row,field,removed}}:", cut.len());
269	    for &(row, field, removed) in cut {
270	        let name = opts.fields.get(field).map_or("", String::as_str);
271	        let _ = writeln!(out, "  {row},{},{removed}", escape_value(name));
272	    }
273	}
