275	/// Owns [`ToonDocument`] in a module of its own -- containing nothing else
276	/// -- so the invariant "only `validate` can produce one" is enforced by
277	/// Rust's own field-privacy rule, not by scanning source text for known
278	/// bypass shapes. `opts` is visible only inside this module and its
279	/// descendants; since this module declares no descendants and nothing
280	/// besides `validate`/`render`, no code anywhere else in this crate --
281	/// regardless of what shape it takes (a free function, a second impl
282	/// block, a `From`/`TryFrom` impl, a type alias, or a module gated behind
283	/// an unanticipated `#[cfg(...)]`) -- can write the struct-literal
284	/// `ToonDocument { opts }` and have it compile. This module is `mod`, not
285	/// `pub`, so external code cannot even name `render::proof::ToonDocument`
286	/// directly; the type is reachable only through the `pub use` re-export
287	/// below.
288	///
289	/// This guarantee holds only GIVEN two preconditions that Rust's type
290	/// system does not itself enforce, and that are each pinned by a
291	/// dedicated assertion in `sole_constructor_for_toon_document` rather than
292	/// left as a precondition nothing verifies: (1) `opts` stays genuinely
293	/// bare-private -- widening its visibility to reach the rest of this
294	/// module is a one-token, entirely ordinary-looking edit that would grant
295	/// field access to all of `render.rs` and let a constructor live outside
296	/// `proof` entirely, defeating the guarantee above while every OTHER
297	/// check here stays green; and (2) `proof`'s true extent is what the
298	/// scanning code believes it is -- found, historically, to be defeatable
299	/// by a multi-line string literal (e.g. inside a `#[doc = "..."]`
300	/// attribute) containing a bare `}`, which an earlier, purely line-based
301	/// brace-matcher mistook for the module's real close. `find_closing_line`
302	/// now tracks actual lexical structure (string and char literals,
303	/// comments) rather than taking for granted that a closing brace is
304	/// always alone on its rustfmt-normalized line, closing that specific
305	/// hole; a companion assertion additionally pins the literal line
306	/// immediately following `proof`'s close, as
307	/// defense in depth against a future defect in that scan.
308	///
309	/// **Known, accepted residual:** none of the above closes a bypass hidden
310	/// behind `macro_rules!` expansion -- a `some_macro!();` item-position
311	/// invocation inside this module's own `impl` block is, after expansion,
312	/// code that genuinely lives inside `proof` and therefore has real field
313	/// access, the same way `validate` does. No text scan can see through
314	/// macro expansion (`include_str!`, which every guard test here reads
315	/// from, captures source as written, before expansion), so this is a
316	/// limit of the mechanism, not a missed pattern. Per this invariant's own
317	/// design record, the property being enforced is that a maintainer
318	/// *following this codebase's patterns* cannot reintroduce the defect by
319	/// accident; a maintainer deliberately writing macro-hidden field access
320	/// to evade this exact module boundary is choosing to defeat it, not
321	/// accidentally tripping over it, and is outside what a source-level
322	/// guard can mechanically prevent. Closing that residual for real would
323	/// mean asserting over post-expansion, cfg-resolved output (e.g. via
324	/// `cargo-expand`) rather than unexpanded source text -- a deliberate
325	/// scope decision, not an oversight.
326	mod proof {
327	    /// Proof that a `ToonOptions` value has passed structural validation.
328	    ///
329	    /// The only function that produces a `ToonDocument` is
330	    /// [`ToonDocument::validate`] -- see this module's own doc comment for
331	    /// why no other function anywhere in the crate can construct one.
332	    /// Borrows `&'a ToonOptions` immutably, so the validated options cannot
333	    /// be mutated while the proof is live.
334	    #[derive(Debug)]
335	    pub struct ToonDocument<'a> {
336	        opts: &'a crate::toon::ToonOptions,
337	    }
338	
339	    impl<'a> ToonDocument<'a> {
340	        /// Validate `opts` and return a proof it satisfies every structural
341	        /// invariant [`ToonDocument::render`] depends on.
342	        ///
343	        /// Every type name and field name is encodable (TOON 4.4 §7.3 quotes
344	        /// the ones that need it), so validation only rejects options that
345	        /// would make the document itself invalid TOON.
346	        ///
347	        /// # Errors
348	        ///
349	        /// Checks run in this order and the first failure is returned:
350	        /// [`crate::toon::ToonError::InvalidTypeName`] if `type_name` is a
351	        /// reserved root key (`totalCount`, `help`, `recovery` or `truncated`),
352	        /// [`crate::toon::ToonError::TooManyFields`] past
353	        /// [`crate::toon::MAX_FIELDS`] fields,
354	        /// [`crate::toon::ToonError::InvalidFieldName`] if a field name appears
355	        /// more than once, [`crate::toon::ToonError::TooManyCells`] if
356	        /// `rows × fields` (at least one cell per row) is past [`crate::toon::MAX_CELLS`],
357	        /// [`crate::toon::ToonError::TruncationHintTooLong`] if the truncation
358	        /// hint is past [`crate::toon::MAX_TRUNCATION_HINT_CHARS`] chars, and
359	        /// [`crate::toon::ToonError::RowLengthMismatch`] if any row's length
360	        /// differs from `fields.len()`. Every check is linear in the input.
361	        pub fn validate(opts: &'a crate::toon::ToonOptions) -> Result<Self, crate::toon::ToonError> {
362	            use crate::toon::{ToonError, MAX_CELLS, MAX_FIELDS, MAX_TRUNCATION_HINT_CHARS};
363	            if super::RESERVED_TYPE_NAMES.contains(&opts.type_name.as_str()) {
364	                return Err(ToonError::InvalidTypeName { name: opts.type_name.clone() });
365	            }
366	            if opts.fields.len() > MAX_FIELDS {
367	                return Err(ToonError::TooManyFields { count: opts.fields.len(), max: MAX_FIELDS });
368	            }
369	            let mut seen = std::collections::HashSet::with_capacity(opts.fields.len());
370	            for field in &opts.fields {
371	                if !seen.insert(field.as_str()) {
372	                    return Err(ToonError::InvalidFieldName { name: field.clone() });
373	                }
374	            }
375	            if crate::toon::cell_count(opts.rows.len(), opts.fields.len()) > MAX_CELLS {
376	                return Err(ToonError::TooManyCells {
377	                    rows: opts.rows.len(),
378	                    fields: opts.fields.len(),
379	                    max: MAX_CELLS,
380	                });
381	            }
382	            if let Some(hint) = &opts.truncation_hint {
383	                // A hint of at most MAX bytes has at most MAX chars, so only a longer one needs counting.
384	                if hint.len() > MAX_TRUNCATION_HINT_CHARS {
385	                    let len = hint.chars().count();
386	                    if len > MAX_TRUNCATION_HINT_CHARS {
387	                        return Err(ToonError::TruncationHintTooLong { len, max: MAX_TRUNCATION_HINT_CHARS });
388	                    }
389	                }
390	            }
391	            for (i, row) in opts.rows.iter().enumerate() {
392	                if row.len() != opts.fields.len() {
393	                    return Err(ToonError::RowLengthMismatch {
394	                        row_index: i,
395	                        expected: opts.fields.len(),
396	                        actual: row.len(),
397	                    });
398	                }
399	            }
400	            Ok(Self { opts })
401	        }
402	
403	        /// Render `self` to a TOON 4.4 document: the list entry, then
404	        /// `totalCount: N` and the inline `help[N]: …` array when present,
405	        /// with no trailing newline (§12). Infallible and total by
406	        /// construction: row arity was already proven equal to
407	        /// `fields.len()` by `validate`, so rows and fields are iterated in
408	        /// lockstep instead of indexed by position, which could fail.
409	        ///
410	        /// Cells cut to `max_cell_len` end in `…` and are reported in a `truncated[N]{row,field,removed}:` block
411	        /// after the list. When [`ToonOptions::truncation_hint`](crate::toon::ToonOptions::truncation_hint) is set
412	        /// and a cell was cut, michi adds one line to `help[]` pointing at that block and the caller's instruction.
413	        #[must_use]
414	        pub fn render(&self) -> String {
415	            let (mut out, _, extra) = self.render_parts(true);
416	            let hints = self.opts.hints.iter().map(String::as_str).chain(extra.as_deref());
417	            let hints: Vec<&str> = hints.collect();
418	            crate::hints::append_help_block(&mut out, hints.into_iter());
419	            out
420	        }
421	
422	        /// The document without its `help` block, plus the `help[]` line michi adds when it cut a cell and the
423	        /// caller set a truncation hint. [`AgentResponse`](crate::AgentResponse) merges that line into its own
424	        /// hints so a response keeps a single `help` key.
425	        ///
426	        /// With `inline` the `truncated` block and `totalCount` line follow the list and the cut list returned is
427	        /// empty. Without it the text is the list entry alone and the cuts come back as `(row, field name, chars
428	        /// removed)`, so a multi-section response can merge the cuts of every block into one `truncated` table.
429	        pub(crate) fn render_parts(&self, inline: bool) -> (String, Vec<(usize, String, usize)>, Option<String>) {
430	            let opts = self.opts;
431	            let capacity = 60 + opts.rows.len() * (opts.fields.len() * 12 + 10);
432	            let mut out = String::with_capacity(capacity);
433	            let cut = super::push_list(&mut out, opts);
434	            let extra = match opts.truncation_hint.as_deref() {
435	                Some(hint) if !cut.is_empty() && !hint.is_empty() => {
436	                    Some(format!("Cut cells are listed in the truncated block; use {hint} for the full value"))
437	                }
438	                _ => None,
439	            };
440	            let mut cuts = Vec::new();
441	            if inline {
442	                super::push_truncated(&mut out, opts, &cut);
443	                if let Some(total) = opts.total_count {
444	                    out.push_str("totalCount: ");
445	                    out.push_str(&total.to_string());
446	                    out.push('\n');
447	                }
448	            } else {
449	                cuts = cut
450	                    .into_iter()
451	                    .map(|(row, field, removed)| (row, opts.fields.get(field).cloned().unwrap_or_default(), removed))
452	                    .collect();
453	            }
454	            if out.ends_with('\n') {
455	                out.pop();
456	            }
457	            (out, cuts, extra)
458	        }
459	    }
460	}
