848	/// Text-based scanning helpers shared by this crate's structural guard
849	/// tests. `pub(crate)` (not private) so both `render`'s own guard tests
850	/// and `toon/mod.rs`'s (the AC-013 docs guard) can reuse the same,
851	/// independently-hardened implementation instead of each maintaining its
852	/// own copy that can drift out of sync or regress individually.
853	#[cfg(test)]
854	pub(crate) mod test_scan {
855	    /// Finds the byte offset, within `src`, of the `{` that opens
856	    /// `lines[open_line_idx]`'s block -- the first `{` on or after that
857	    /// line's start.
858	    fn brace_byte_offset(lines: &[&str], open_line_idx: usize) -> usize {
859	        let line_start: usize = lines[..open_line_idx].iter().map(|l| l.len() + 1).sum();
860	        line_start + lines[open_line_idx].find('{').expect("opening line must contain '{'")
861	    }
862	
863	    /// Finds the real nesting depth's matching `}` for the `{` at
864	    /// `open_brace_idx` in `src`, and returns the index of the LINE
865	    /// containing that `}` (via a byte-offset -> line-index scan over
866	    /// `lines`).
867	    ///
868	    /// Tracks actual lexical structure -- string literals (including ones
869	    /// that span multiple lines, e.g. inside a `#[doc = "..."]` value),
870	    /// raw strings with any number of `#`s, char literals (including
871	    /// `'\u{XXXX}'` escapes), and `//`/`/* */` comments -- rather than
872	    /// assuming a block's closing brace is always alone on its own
873	    /// rustfmt-normalized line. That assumption is false: rustfmt does not
874	    /// reformat the CONTENTS of a string literal, so a multi-line string
875	    /// (a pasted JSON/TOON example inside a doc comment, for instance)
876	    /// containing a bare `}` at column 0 previously fooled the
877	    /// line-alone-ness check into treating it as the block's real close,
878	    /// silently truncating everything scanned after it -- proven by
879	    /// exit-gate review, which used exactly that shape to hide a second
880	    /// constructor inside what this scan believed was `proof`'s full body.
881	    pub(crate) fn find_closing_line(src: &str, lines: &[&str], open_line_idx: usize, indent: usize) -> usize {
882	        let _ = indent; // kept in the signature for call-site stability; no longer load-bearing
883	        let open_brace_idx = brace_byte_offset(lines, open_line_idx);
884	
885	        #[derive(Clone, Copy, PartialEq)]
886	        enum State {
887	            Normal,
888	            InString,
889	            InRawString(usize),
890	            InLineComment,
891	            InBlockComment,
892	        }
893	
894	        let chars: Vec<char> = src[open_brace_idx..].char_indices().map(|(_, c)| c).collect();
895	        let byte_of: Vec<usize> = src[open_brace_idx..].char_indices().map(|(i, _)| i).collect();
896	        let mut state = State::Normal;
897	        let mut depth = 0i32;
898	        let mut i = 0usize;
899	        while i < chars.len() {
900	            let c = chars[i];
901	            match state {
902	                State::Normal => {
903	                    if c == '"' {
904	                        state = State::InString;
905	                        i += 1;
906	                    } else if c == 'r' && matches!(chars.get(i + 1), Some('"') | Some('#')) {
907	                        let mut hashes = 0usize;
908	                        let mut j = i + 1;
909	                        while chars.get(j) == Some(&'#') {
910	                            hashes += 1;
911	                            j += 1;
912	                        }
913	                        if chars.get(j) == Some(&'"') {
914	                            state = State::InRawString(hashes);
915	                            i = j + 1;
916	                        } else {
917	                            i += 1;
918	                        }
919	                    } else if c == '\'' {
920	                        // A char literal, not a lifetime, only if a closing
921	                        // `'` is found either 2 chars later (plain, e.g.
922	                        // '{') or after a `\...` escape (e.g. '\\', '\'',
923	                        // '\u{XXXX}'). A lifetime ('a, 'static) never has a
924	                        // `'` two-or-few characters later in valid syntax.
925	                        if chars.get(i + 1) == Some(&'\\') {
926	                            if chars.get(i + 2) == Some(&'u') && chars.get(i + 3) == Some(&'{') {
927	                                let close = (i + 4..chars.len())
928	                                    .find(|&k| chars[k] == '}')
929	                                    .expect("unclosed \\u{ escape in char literal");
930	                                i = close + 2; // skip past '}' and the closing '
931	                            } else {
932	                                i += 4; // ' \ x '
933	                            }
934	                        } else if chars.get(i + 2) == Some(&'\'') {
935	                            i += 3; // ' x '
936	                        } else {
937	                            i += 1; // a lifetime; not a char literal
938	                        }
939	                    } else if c == '/' && chars.get(i + 1) == Some(&'/') {
940	                        state = State::InLineComment;
941	                        i += 2;
942	                    } else if c == '/' && chars.get(i + 1) == Some(&'*') {
943	                        state = State::InBlockComment;
944	                        i += 2;
945	                    } else if c == '{' {
946	                        depth += 1;
947	                        i += 1;
948	                    } else if c == '}' {
949	                        depth -= 1;
950	                        if depth == 0 {
951	                            let close_byte = open_brace_idx + byte_of[i];
952	                            return src[..close_byte].matches('\n').count();
953	                        }
954	                        i += 1;
955	                    } else {
956	                        i += 1;
957	                    }
958	                }
959	                State::InString => {
960	                    if c == '\\' {
961	                        i += 2;
962	                    } else if c == '"' {
963	                        state = State::Normal;
964	                        i += 1;
965	                    } else {
966	                        i += 1;
967	                    }
968	                }
969	                State::InRawString(hashes) => {
970	                    if c == '"' && (1..=hashes).all(|k| chars.get(i + k) == Some(&'#')) {
971	                        state = State::Normal;
972	                        i += 1 + hashes;
973	                    } else {
974	                        i += 1;
975	                    }
976	                }
977	                State::InLineComment => {
978	                    if c == '\n' {
979	                        state = State::Normal;
980	                    }
981	                    i += 1;
982	                }
983	                State::InBlockComment => {
984	                    if c == '*' && chars.get(i + 1) == Some(&'/') {
985	                        state = State::Normal;
986	                        i += 2;
987	                    } else {
988	                        i += 1;
989	                    }
990	                }
991	            }
992	        }
993	        panic!("no matching closing brace found for the block opened at line {open_line_idx}");
994	    }
995	
996	    pub(crate) fn indent_of(line: &str) -> usize {
997	        line.len() - line.trim_start().len()
998	    }
999	
1000	    /// Strips every `#[cfg(test)]`/`#[cfg(all(test, ...))]`-gated
1001	    /// `mod ... { ... }` block from `src`, not via a first-occurrence
1002	    /// prefix split -- a prefix split silently stops scanning at the first
1003	    /// test module even if real (non-test) code follows it later in the
1004	    /// file.
1005	    ///
1006	    /// `is_test_cfg_attr` requires `test` as the leading, positive conjunct
1007	    /// of an `all(...)` -- `#[cfg(all(test, ...))]` -- rather than merely
1008	    /// checking whether the attribute's text contains the substring
1009	    /// `"test"` anywhere. A substring check is a real, previously-shipped
1010	    /// bug: `#[cfg(all(not(test), ...))]` also contains `"test"`, so it
1011	    /// would be misclassified as test-only and stripped from this scan,
1012	    /// even though rustc compiles it into every *non*-test build -- the
1013	    /// opposite of test-only. Any other `#[cfg(` line whose text contains
1014	    /// `"test"` and isn't one of the two recognized positive forms trips
1015	    /// the assertion below instead of being silently mishandled in either
1016	    /// direction.
1017	    pub(crate) fn strip_test_modules(src: &str) -> String {
1018	        fn is_recognized_test_cfg_attr(trimmed: &str) -> bool {
1019	            trimmed == "#[cfg(test)]"
1020	                || trimmed.starts_with("#[cfg(all(test,")
1021	                || trimmed.starts_with("#[cfg(all(test)")
1022	        }
1023	
1024	        let lines: Vec<&str> = src.lines().collect();
1025	        let mut kept: Vec<&str> = Vec::with_capacity(lines.len());
1026	        let mut i = 0usize;
1027	        while i < lines.len() {
1028	            let trimmed = lines[i].trim_start();
1029	            if trimmed.starts_with("#[cfg(") && trimmed.contains("test") {
1030	                assert!(
1031	                    is_recognized_test_cfg_attr(trimmed),
1032	                    "unrecognized cfg attribute mentioning \"test\": {trimmed:?} -- add it to \
1033	                     is_recognized_test_cfg_attr only if it is genuinely test-only; a `not(test)` \
1034	                     predicate must NOT be treated as test-only"
1035	                );
1036	                let mod_line = i + 1;
1037	                assert!(
1038	                    lines[mod_line].trim_start().contains("mod ") && lines[mod_line].ends_with('{'),
1039	                    "expected a `[pub(...)] mod ... {{` line immediately after a test cfg attribute, got: {:?}",
1040	                    lines[mod_line]
1041	                );
1042	                let close = find_closing_line(src, &lines, mod_line, indent_of(lines[i]));
1043	                i = close + 1;
1044	            } else {
1045	                kept.push(lines[i]);
1046	                i += 1;
1047	            }
1048	        }
1049	        kept.join("\n")
1050	    }
1051	}
