21	/// Most header fields one TOON list may declare. [`ToonOptions::validate()`] returns [`ToonError::TooManyFields`] past
22	/// it, and `list()` checks it against the union of item keys before building any row.
23	pub const MAX_FIELDS: usize = 1_000;
24	
25	/// Most cells (`rows × fields`) one TOON list may hold, where a list with no fields counts one cell per row (an empty
26	/// row still renders a line). [`ToonOptions::validate()`] returns [`ToonError::TooManyCells`] past it, before looking
27	/// at any row, and `list()` checks it before building rows, so a sparse item set whose key union is wide cannot
28	/// expand into a huge table, and neither can a long list of empty items.
29	pub const MAX_CELLS: usize = 1_000_000;
30	
31	/// The cells [`MAX_CELLS`] counts: `rows × fields`, with at least one cell per row.
32	pub(crate) fn cell_count(rows: usize, fields: usize) -> usize {
33	    rows.saturating_mul(fields.max(1))
34	}
35	
36	/// Longest [`ToonOptions::truncation_hint`], in chars. The hint is a short instruction, not content;
37	/// [`ToonOptions::validate()`] returns [`ToonError::TruncationHintTooLong`] past it.
38	pub const MAX_TRUNCATION_HINT_CHARS: usize = 256;
