40	/// Error returned by [`ToonOptions::validate()`] when the options cannot form a valid TOON document.
41	#[derive(Debug, Clone, PartialEq)]
42	#[non_exhaustive]
43	pub enum ToonError {
44	    /// `type_name` is a root key michi composes next to a list (`totalCount`, `help`, `recovery` or `truncated`); using it would
45	    /// emit a duplicate key, which TOON 4.4 §14.3 forbids. Any other name is valid and is quoted when §7.3 requires.
46	    InvalidTypeName {
47	        /// The offending name.
48	        name: String,
49	    },
50	    /// A field name appears more than once in `fields`; a repeated field name in one header is invalid TOON (§14.2).
51	    /// Any other name is valid and is quoted when §7.3 requires.
52	    InvalidFieldName {
53	        /// The offending field name.
54	        name: String,
55	    },
56	    /// Row `row_index` has `actual` values but `fields` declares `expected`.
57	    RowLengthMismatch {
58	        /// Zero-based index of the mismatched row.
59	        row_index: usize,
60	        /// Number of fields declared in the header.
61	        expected: usize,
62	        /// Actual number of values in the row.
63	        actual: usize,
64	    },
65	    /// An item in `list()` (`serde` feature) could not be rendered as a TOON row.
66	    ///
67	    /// Items must serialize to a JSON object (`serde_json::Value::Object`).
68	    /// Scalars, arrays, and `null` values cannot be represented as TOON rows.
69	    InvalidItem {
70	        /// Zero-based index of the invalid item.
71	        row_index: usize,
72	        /// Reason why the item is invalid.
73	        reason: String,
74	    },
75	    /// `fields` declares more than [`MAX_FIELDS`] names (for `list()`: the items' keys add up to more).
76	    TooManyFields {
77	        /// Number of fields declared.
78	        count: usize,
79	        /// The limit, [`MAX_FIELDS`].
80	        max: usize,
81	    },
82	    /// `rows × fields` (at least one cell per row) is more than [`MAX_CELLS`].
83	    TooManyCells {
84	        /// Number of rows.
85	        rows: usize,
86	        /// Number of fields.
87	        fields: usize,
88	        /// The limit, [`MAX_CELLS`].
89	        max: usize,
90	    },
91	    /// [`ToonOptions::truncation_hint`] is longer than [`MAX_TRUNCATION_HINT_CHARS`] chars.
92	    TruncationHintTooLong {
93	        /// Length of the hint, in chars.
94	        len: usize,
95	        /// The limit, [`MAX_TRUNCATION_HINT_CHARS`].
96	        max: usize,
97	    },
98	}
