100	impl std::fmt::Display for ToonError {
101	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
102	        match self {
103	            Self::InvalidTypeName { name } => {
104	                write!(f, "type_name {name:?} is a reserved document key (totalCount, help, recovery, truncated)")
105	            }
106	            Self::InvalidFieldName { name } => {
107	                write!(f, "field {name:?} appears more than once")
108	            }
109	            Self::RowLengthMismatch { row_index, expected, actual } => {
110	                write!(f, "row {row_index} has {actual} values but {expected} fields declared")
111	            }
112	            Self::InvalidItem { row_index, reason } => {
113	                write!(f, "item at index {row_index} cannot be rendered as a TOON row: {reason}")
114	            }
115	            Self::TooManyFields { count, max } => write!(f, "fields length {count} exceeds maximum of {max}"),
116	            Self::TooManyCells { rows, fields, max } => {
117	                let cells = cell_count(*rows, *fields);
118	                write!(f, "{rows} rows x {fields} fields = {cells} cells exceeds maximum of {max}")
119	            }
120	            Self::TruncationHintTooLong { len, max } => {
121	                write!(f, "truncation_hint length {len} chars exceeds maximum of {max}")
122	            }
123	        }
124	    }
125	}
