129	/// Options for rendering a TOON document.
130	#[derive(Debug, Clone, PartialEq)]
131	#[non_exhaustive]
132	pub struct ToonOptions {
133	    /// Snake_case type name, e.g. `"issue"`, `"component"`: the key of the list entry. Names outside TOON's
134	    /// unquoted-key pattern are quoted (§7.3); `totalCount`, `help`, `recovery` and `truncated` are reserved.
135	    pub type_name: String,
136	    /// Ordered, distinct field names for the header, e.g. `["number", "title", "state"]`, quoted when §7.3 requires.
137	    /// Not emitted when `rows` is empty (an empty list renders as `type: []`).
138	    pub fields: Vec<String>,
139	    /// Rows, each a Vec of values parallel to `fields`. Rows with zero fields are empty objects and render as bare
140	    /// `-` list items, since TOON forbids a tabular form without fields.
141	    pub rows: Vec<Vec<Value>>,
142	    /// Total available count (emitted as `totalCount: N` when `Some`).
143	    pub total_count: Option<usize>,
144	    /// Agent-facing usage hints. Emitted as the inline array `help[N]: h1,h2` when non-empty.
145	    pub hints: Vec<String>,
146	    /// Max string cell length, in chars, before truncation. Default: 200.
147	    ///
148	    /// The cap counts the cell's characters *before* TOON escaping and quoting: a truncated (or untruncated) cell
149	    /// that needs quotes or escapes (§7.1, §7.2) is written longer than `max_cell_len` on the wire. A longer cell keeps
150	    /// its first `max_cell_len - 1` chars and ends in a plain `…` (the empty string for a cap of 0). The cell carries
151	    /// no message: every cut cell is reported in a `truncated[N]{row,field,removed}:` block after the list, which
152	    /// cell text cannot forge because cells are quoted and escaped.
153	    pub max_cell_len: usize,
154	    /// The caller's instruction for getting a truncated cell in full, e.g. `"full=true"` or `"--no-truncate"`.
155	    /// Default `None`: michi never invents a parameter the calling tool may not have. When set and a cell was cut,
156	    /// michi adds one `help[]` line naming the `truncated` block and this instruction. It comes from the tool author,
157	    /// never from data. An empty string is the same as `None`.
158	    pub truncation_hint: Option<String>,
