242	/// Render a TOON 4.4 document to a string (no trailing newline).
243	///
244	/// # Errors
245	///
246	/// Returns [`ToonError`] if `opts` fails structural validation — see
247	/// [`ToonOptions::validate`] for the exact conditions.
248	pub fn render_toon(opts: &ToonOptions) -> Result<String, ToonError> {
249	    opts.validate().map(|doc| doc.render())
250	}
