252	#[cfg(feature = "serde")]
253	fn json_value_to_toon_value(v: Option<&serde_json::Value>) -> Value {
254	    match v {
255	        None | Some(serde_json::Value::Null) => Value::Null,
256	        Some(serde_json::Value::Bool(b)) => Value::Bool(*b),
257	        Some(serde_json::Value::Number(n)) => {
258	            if let Some(i) = n.as_i64() {
259	                Value::Int(i)
260	            } else if let Some(u) = n.as_u64() {
261	                // Above i64::MAX: an exact unsigned number, not rounded through f64.
262	                Value::UInt(u)
263	            } else if let Some(f) = n.as_f64() {
264	                Value::Float(f)
265	            } else {
266	                Value::Str(compact_str::CompactString::new(n.to_string()))
267	            }
268	        }
269	        Some(serde_json::Value::String(s)) => Value::Str(compact_str::CompactString::new(s)),
270	        Some(other) => Value::Str(compact_str::CompactString::new(other.to_string())),
271	    }
272	}
