274	/// Build and render a TOON document from a slice of `Serialize`-able items.
275	///
276	/// Returns the rendered TOON string on success. Returns `Err` if any item
277	/// does not serialize to a JSON object (e.g. a bare integer or string slice)
278	/// — use only with homogeneous struct slices.
279	///
280	/// The header lists every field any item serialized, in first-seen order, so a field skipped on early rows (for
281	/// example `#[serde(skip_serializing_if = "Option::is_none")]`) still appears. Rows without that field get a `null`
282	/// cell.
283	///
284	/// Host-type normalization (TOON 4.4 §3): JSON integers map to [`Value::Int`], or [`Value::UInt`] above `i64::MAX`;
285	/// other numbers to [`Value::Float`] (and, only with serde_json's `arbitrary_precision`, a number outside both domains
286	/// becomes a string of its exact digits); a missing key or JSON `null` to `null`; and a nested array or object to a
287	/// string holding its compact JSON text, since michi emits flat tables only.
288	///
289	/// Requires the `serde` feature.
290	///
291	/// # Errors
292	///
293	/// Returns [`ToonError::InvalidItem`] if an item fails to serialize or does
294	/// not produce a JSON object (struct or map required). Returns
295	/// [`ToonError::InvalidTypeName`] if `type_name` is a reserved root key
296	/// (`totalCount`, `help`, `recovery` or `truncated`). Returns [`ToonError::TooManyFields`] if the items' keys add up to more than
297	/// [`MAX_FIELDS`] distinct names, or [`ToonError::TooManyCells`] if `items.len()` times that header width is past
298	/// [`MAX_CELLS`]; both are checked before any row is built.
299	#[cfg_attr(docsrs, doc(cfg(feature = "serde")))]
300	#[cfg(feature = "serde")]
301	pub fn list<T: serde::Serialize>(type_name: impl Into<String>, items: &[T]) -> Result<String, ToonError> {
302	    let type_name = type_name.into();
303	    let mut fields: Vec<String> = Vec::new();
304	    let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();
305	    let mut objects: Vec<serde_json::Map<String, serde_json::Value>> = Vec::with_capacity(items.len());
306	    for (row_index, item) in items.iter().enumerate() {
307	        // Through JSON text rather than `serde_json::to_value`: the text writer prints an `f32` with its own shortest
308	        // digits (`0.1`), while `to_value` widens it to f64 first (`0.10000000149011612`). Reading the text back is
309	        // exact for every other value (`float_roundtrip` is on).
310	        let obj = match serde_json::to_vec(item).and_then(|text| serde_json::from_slice(&text)) {
311	            Ok(serde_json::Value::Object(map)) => map,
312	            Ok(_) => {
313	                return Err(ToonError::InvalidItem {
314	                    row_index,
315	                    reason: "item is not a JSON object (struct or map required)".into(),
316	                });
317	            }
318	            Err(e) => {
319	                return Err(ToonError::InvalidItem { row_index, reason: e.to_string() });
320	            }
321	        };
322	        for key in obj.keys() {
323	            if seen.insert(key.clone()) {
324	                fields.push(key.clone());
325	            }
326	        }
327	        objects.push(obj);
328	    }
329	    // Check the shape before building rows: a sparse item set whose key union is wide would otherwise expand into
330	    // rows × fields cells here, before validate() could reject it.
331	    if !render::RESERVED_TYPE_NAMES.contains(&type_name.as_str()) {
332	        if fields.len() > MAX_FIELDS {
333	            return Err(ToonError::TooManyFields { count: fields.len(), max: MAX_FIELDS });
334	        }
335	        if cell_count(objects.len(), fields.len()) > MAX_CELLS {
336	            return Err(ToonError::TooManyCells { rows: objects.len(), fields: fields.len(), max: MAX_CELLS });
337	        }
338	    }
339	    let rows: Vec<Vec<Value>> =
340	        objects.iter().map(|obj| fields.iter().map(|f| json_value_to_toon_value(obj.get(f))).collect()).collect();
341	    let opts = ToonOptions::new(type_name, fields, rows);
342	    Ok(opts.validate()?.render())
343	}
